rhs_question_text:
A school web quiz reads answers from HTML response elements, compares each with the correct answer and writes feedback. Fill the five blanks in this original JavaScript function. [5]

function markQuiz(responseIds, feedbackIds, ____________) {
  let ____________ = 0;
  for (let qCount = 0; qCount < responseIds.length; qCount++) {
    const response = document.getElementById(responseIds[qCount]).textContent;
    const expected = answers[____________];
    if (response === expected) {
      score = ____________;
      document.getElementById(feedbackIds[qCount]).textContent = 'Correct';
    }
  }
  ____________ score;
}
